head.script:
// 원본 : JLDFIL00170 공시서류 작성 대상회사·대상종목 선택 (/ui/sample/template/JLDFIL00170.xml)

/*
 * 화면 동작
 * 1. 화면 로딩시 이전 화면이 넘긴 서식 정보를 받고, 로그인 발행사를 대상회사 칸에 기본값으로 채움
 * 2. 「발행사 거래소고유번호」 돋보기 클릭시 법인명 찾기 팝업 호출 → 고른 법인으로 대상회사 3칸을 채우고 대상종목은 비움
 * 3. 「대상 종목코드」 돋보기 클릭시 대상회사의 종목 선택 팝업 호출 → 고른 종목으로 대상종목 2칸을 채움
 * 4. 「확인」 클릭시 대상회사·대상종목 선택 여부 검증 → 공시서류 등록 → 발급된 접수번호로 작성 화면 이동
 *
 * 담긴 패턴
 * - 이전 화면 파라미터 수신 ($c.data.getParameter) 과 로그인 사용자 정보로 기본값 채우기 ($c.session.getUserInfo)
 * - 값을 돌려주는 선택 팝업 2종 ($c.win.openPopup 을 await 로 수신, 취소는 필요한 키의 유무로 판단)
 * - 읽기전용 입력칸의 필수 검증 ($c.validate.validateDataCollect 의 focus 옵션으로 돋보기 버튼에 포커스)
 * - 선행 선택(대상회사)이 바뀌면 후행 선택(대상종목)을 비우는 종속 입력 처리
 * - 등록 통신 (executeDynamic) 후 응답값 검사와 화면 이동 ($c.win.moveUrl)
 *
 * 변환 샘플과 달라진 곳
 * - 원본은 디지털 구분(digitalType 1 / 2 / 없음)마다 같은 표를 세 벌 그려 두고 조건으로 하나만 보였다.
 *   이 샘플은 화면 이미지와 같은 "회사 + 종목" 구성 한 벌만 담았다. 회사만 고르는 화면은 종목 영역과 findIsu·setIsu·clearIsu 를 지우면 된다.
 * - 항목별 "빈값 → alert → return" 나열(회사 3칸·종목 2칸을 세 번 반복)을 validateDataCollect 한 건으로 통합했다.
 * - 팝업 결과를 부모 함수 호출(setCorpInfo / setIsuInfo)로 받던 것을 openPopup 의 await 반환값으로 받는다.
 * - 등록 응답을 서버 렌더 페이지로 받던 것을 JSON 응답(접수번호)으로 받아 작성 화면으로 이동한다.
 * - 같은 전문 키를 두 번씩 담던 중복 set 과 미사용 전역(moveStep)을 삭제했다.
 *
 * 복사해서 쓰는 순서
 * 1. 파일명과 meta_screenId 를 실제 화면ID 로 변경
 * 2. 1구역의 팝업 경로·작성 화면 경로 상수와 세션 키 이름을 프로젝트 규약에 맞게 교체
 * 3. dma_in 키와 registerDisclosure 의 action 을 실 API 로 교체
 * 4. 팝업이 돌려주는 키 이름을 setCompany·setIsu 에서 맞춤
 */


///////// 1. 변수 및 선언 영역 /////////

scwin.screenId = "JLDFIL00170";

// 이전 화면(서식 선택)에서 넘겨받는 값
scwin.formCd = "";          // 서식코드
scwin.formVer = "";         // 서식버전
scwin.submitDiv = "";       // 제출구분

// 선택 팝업·이동 화면 경로 — 복사해 쓸 때 프로젝트 경로로 바꾼다.
scwin.CORP_POPUP_URL = "/ui/sample/template/JLDFIL00018.xml";   // 법인명 찾기 팝업 (같은 샘플 묶음)
scwin.ISU_POPUP_URL = "/ui/jsp/JLDFIL00033.xml";                // 종목 선택 팝업 (원본 계약 — method : loadInitPageIsu)
scwin.WRITE_URL = "/ui/jsp/JLDFIL00180.xml";                    // 공시서류 작성 화면


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 14
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        // 초기화 함수
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "JLDFIL00170.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 14
 * @description 초기화. 이전 화면이 넘긴 서식 정보를 받고, 로그인 발행사를 대상회사 기본값으로 채운다.
 *
 * 원본은 서버가 세션의 발행사 코드·금감원고유번호를 hidden 으로 그려 두고 스크립트가 DOM 으로 읽었다.
 * 여기서는 로그인 사용자 정보를 공통($c.session.getUserInfo)에서 바로 읽는다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 받는 파라미터 이름 (formCd·formVer·submitDiv)
 *  - 사용자 정보의 키 이름 (isurCd·fssUnqNo·comAbbrv) — 프로젝트 세션 전문에 맞춘다
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    const param = $c.data.getParameter() ?? {};

    scwin.formCd = param.formCd ?? "";
    scwin.formVer = param.formVer ?? "";
    scwin.submitDiv = param.submitDiv ?? "";

    // 로그인 발행사를 대상회사 기본값으로 — 다른 법인을 대상으로 하면 돋보기로 바꾼다.
    const userInfo = $c.session.getUserInfo() ?? {};

    scwin.setCompany({
        isurCd : userInfo.isurCd,
        fssUnqNo : userInfo.fssUnqNo,
        comAbbrv : userInfo.comAbbrv
    });
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_findCompany_onclick
 * @author Inswave
 * @date 2026. 10. 14
 * @description 발행사 거래소고유번호 돋보기 클릭. 법인명 찾기 팝업에서 고른 법인으로 대상회사를 채운다.
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_findCompany_onclick = async function (e) {
    try {
        await scwin.findCompany();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "JLDFIL00170.btn_findCompany_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_findIsu_onclick
 * @author Inswave
 * @date 2026. 10. 14
 * @description 대상 종목코드 돋보기 클릭. 대상회사의 종목 선택 팝업에서 고른 종목으로 대상종목을 채운다.
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_findIsu_onclick = async function (e) {
    try {
        await scwin.findIsu();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "JLDFIL00170.btn_findIsu_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_confirm_onclick
 * @author Inswave
 * @date 2026. 10. 14
 * @description 확인 클릭. 선택값을 검증하고 공시서류를 등록해 작성 화면으로 이동한다.
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_confirm_onclick = async function (e) {
    try {
        await scwin.goWrite();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "JLDFIL00170.btn_confirm_onclick" });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.registerDisclosure
 * @author Inswave
 * @date 2026. 10. 14
 * @description 공시서류 등록. 선택한 대상회사·대상종목과 서식 정보를 보내고 발급된 접수번호를 돌려받는다.
 *
 * 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던지므로 여기서는 업무 응답만 본다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action 경로와 dma_in 키
 *  - 응답에서 접수번호를 꺼내는 키 이름 (applNo)
 * @param
 * @returns {Promise<String>} 접수번호 (등록 실패·중복 제출이면 빈 문자열)
 * @hidden N
*/
scwin.registerDisclosure = async function () {
    dma_in.setEmptyValue();
    dma_in.setJSON(dma_item.getJSON());

    dma_in.set("formCd", scwin.formCd);
    dma_in.set("formVer", scwin.formVer);
    dma_in.set("submitDiv", scwin.submitDiv);
    dma_in.set("corpisuBasTpCd", "2");     // 법인종목기준유형 2: 종목 기준 (회사만 고르는 화면이면 "1")

    const sbmOptions = {
        id : "sbm_registerDisclosure",
        method : "post",
        action : "/api/submission/disclosure/register",
        mediatype : "application/json",
        ref : "dma_in",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);

    // 같은 요청이 진행 중이면 공통이 두 번째 제출을 건너뛴다.
    if (result?.skipped) return "";

    if (!result.responseJSON?.success) {
        await $c.win.alert(result.responseJSON?.message ?? "공시서류 등록에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.");
        return "";
    }

    return String(result.responseJSON.body?.applNo ?? "");
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.findCompany
 * @author Inswave
 * @date 2026. 10. 14
 * @description 법인명 찾기 팝업을 열어 고른 법인으로 대상회사를 채운다.
 *
 * 값을 돌려주는 선택 팝업이라 결과에 발행사 코드가 있는지로 취소를 판단한다
 * (취소·X 닫기에도 { isCloseButtonClick } 객체가 오므로 isEmpty(result) 로는 가릴 수 없다).
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 팝업 경로(CORP_POPUP_URL)·크기·넘길 파라미터·반환 키 이름
 * @param
 * @returns
 * @hidden N
*/
scwin.findCompany = async function () {
    const options = {
        id : "JLDFIL00018",
        popupName : "법인명 찾기",
        type : "pageFramePopup",
        width : 600,
        height : 660
    };

    // 팝업이 조회하는 시장구분 — 유가 : stockMkt, 코스닥 : kosdaqMkt, 코넥스 : konexMkt, 연계공시 : forLink
    const param = {
        marketType : "stockMkt",
        formCd : scwin.formCd
    };

    const result = await $c.win.openPopup(scwin.CORP_POPUP_URL, options, param);

    // 선택 없이 닫으면 발행사 코드가 없다.
    if ($c.util.isEmpty(result.isurCd)) return;

    scwin.setCompany(result);
};

/**
 * @method
 * @name scwin.findIsu
 * @author Inswave
 * @date 2026. 10. 14
 * @description 대상회사의 종목 선택 팝업을 열어 고른 종목으로 대상종목을 채운다.
 *
 * 대상회사가 먼저 정해져 있어야 그 회사의 종목을 조회할 수 있다.
 * 종목 선택 팝업의 전환본은 이 샘플 묶음에 없어 원본 계약(method : loadInitPageIsu, 반환 isurCd·repIsuCd·repIsuSrtCd·isuKorNm·isuKorAbbrv·fssUnqNo)으로 적었다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 팝업 경로(ISU_POPUP_URL)·크기·넘길 파라미터·반환 키 이름
 * @param
 * @returns
 * @hidden N
*/
scwin.findIsu = async function () {
    if ($c.util.isEmpty(dma_item.get("tgtIsurCd"))) {
        await $c.win.alert("공시제출 대상회사를 먼저 선택하십시오.");
        btn_findCompany.focus();
        return;
    }

    const options = {
        id : "JLDFIL00033",
        popupName : "종목 선택",
        type : "pageFramePopup",
        width : 600,
        height : 660
    };

    const param = {
        method : "loadInitPageIsu",
        isurCd : dma_item.get("tgtIsurCd"),
        formCd : scwin.formCd
    };

    const result = await $c.win.openPopup(scwin.ISU_POPUP_URL, options, param);

    // 선택 없이 닫으면 종목코드가 없다.
    if ($c.util.isEmpty(result.repIsuCd)) return;

    scwin.setIsu(result);
};

/**
 * @method
 * @name scwin.setCompany
 * @author Inswave
 * @date 2026. 10. 14
 * @description 대상회사 3칸을 채운다. 회사가 바뀌면 그 회사의 종목이 아니므로 대상종목은 비운다.
 *
 * 로그인 발행사(init)와 법인명 찾기 팝업 결과가 같은 키 이름(isurCd·fssUnqNo·comAbbrv)으로 들어온다.
 * @param {Object} data 법인 정보
 * @param {String} data.isurCd 발행사 거래소고유번호
 * @param {String} data.fssUnqNo 발행사 금감원고유번호
 * @param {String} data.comAbbrv 회사약명
 * @returns
 * @hidden N
*/
scwin.setCompany = function (data) {
    dma_item.set("tgtIsurCd", data.isurCd ?? "");
    dma_item.set("tgtFssUnqNo", data.fssUnqNo ?? "");
    dma_item.set("tgtComNm", data.comAbbrv ?? "");

    scwin.clearIsu();
};

/**
 * @method
 * @name scwin.setIsu
 * @author Inswave
 * @date 2026. 10. 14
 * @description 대상종목 2칸을 채운다. 단축코드는 전문에만 담기고 화면에는 보이지 않는다.
 * @param {Object} data 종목 정보
 * @param {String} data.repIsuCd 종목코드
 * @param {String} data.repIsuSrtCd 종목단축코드
 * @param {String} data.isuKorAbbrv 종목 한글약명
 * @returns
 * @hidden N
*/
scwin.setIsu = function (data) {
    dma_item.set("tgtIsuCd", data.repIsuCd ?? "");
    dma_item.set("tgtIsuSrtCd", data.repIsuSrtCd ?? "");
    dma_item.set("tgtIsuNm", data.isuKorAbbrv ?? "");
};

/**
 * @method
 * @name scwin.clearIsu
 * @author Inswave
 * @date 2026. 10. 14
 * @description 대상종목 칸을 비운다.
 * @param
 * @returns
 * @hidden N
*/
scwin.clearIsu = function () {
    dma_item.set("tgtIsuCd", "");
    dma_item.set("tgtIsuSrtCd", "");
    dma_item.set("tgtIsuNm", "");
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 14
 * @description 확인 전 대상회사·대상종목이 선택됐는지 검증한다.
 *
 * 입력칸이 전부 읽기전용이라 focus 옵션으로 돋보기 버튼에 포커스를 준다
 * (실패 시 표준 alert 과 포커스를 공통이 처리, async 라 await 필요).
 * 회사 3칸·종목 2칸은 팝업이 한 번에 채우므로 대표 칸 하나씩만 검증한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - options.fields 검증 항목 (키 = 컴포넌트 ID)
 * @param
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
*/
scwin.validate = async function () {
    const options = {
        validateType : "alert",     // alert|mark|all
        checkType : "single",       // single|multi
        fields : {
            ipt_tgtIsurCd : { required : true, message : "공시제출 대상회사를 선택하십시오.", focus : "btn_findCompany", name : "대상회사" },
            ipt_tgtIsuCd : { required : true, message : "공시제출 대상종목을 선택하십시오.", focus : "btn_findIsu", name : "대상종목" }
        }
    };

    return await $c.validate.validateDataCollect(grp_form, options);
};

/**
 * @method
 * @name scwin.goWrite
 * @author Inswave
 * @date 2026. 10. 14
 * @description 선택값을 검증하고 공시서류를 등록한 뒤, 발급된 접수번호로 작성 화면으로 이동한다.
 *
 * 접수번호는 14자리다. 길이가 다르면 등록은 됐어도 문서를 불러올 수 없으므로 안내하고 멈춘다(원본 registerProcess 의 판정).
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 작성 화면 경로(WRITE_URL)와 넘길 파라미터
 * @param
 * @returns
 * @hidden N
*/
scwin.goWrite = async function () {
    if (!await scwin.validate()) return;

    const applNo = await scwin.registerDisclosure();

    if ($c.util.isEmpty(applNo)) return;

    if ($c.str.getByteLength(applNo) !== 14) {
        await $c.win.alert("문서불러오기에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.");
        return;
    }

    $c.win.moveUrl(scwin.WRITE_URL, {
        applNo : applNo,
        formCd : scwin.formCd,
        formVer : scwin.formVer,
        submitDiv : scwin.submitDiv
    });
};
